use std::{fs,path::Path,process::{Command,Stdio}};
fn main(){let dir=std::env::args().nth(1).unwrap();let root=Path::new(&dir);assert!(!root.exists());fs::create_dir(root).unwrap();let bin=std::env::current_exe().unwrap().with_file_name("fieldchart-all13");let mut supported=0;let mut unsupported=0;for p in [97,257,509,1009]{let s=Command::new(&bin).arg(p.to_string()).stdout(Stdio::from(fs::File::create(root.join(format!("p{p}.stdout"))).unwrap())).stderr(Stdio::from(fs::File::create(root.join(format!("p{p}.stderr"))).unwrap())).status().unwrap();fs::write(root.join(format!("p{p}.status")),format!("exit={:?}\n",s.code())).unwrap();if s.success(){supported+=1;println!("SUPPORTED p={p}");}else{let err=fs::read_to_string(root.join(format!("p{p}.stderr"))).unwrap();assert!(s.code()==Some(101)&&err.contains("no_supported_anchor_all_affine"),"unexpected_field_failure p={p}");unsupported+=1;println!("UNSUPPORTED p={p} all_affine_origins_checked=true");}}println!("COHORT_COMPLETE cases=4 supported={supported} unsupported={unsupported} dlp_or_timing_claim=false");}
